import{z as B,x as A,o as e,c as d,q as r,j as t,D as o,d as n,s as l,S as i,b as s}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"Bossung 曲线","description":"","frontmatter":{"title":"Bossung 曲线","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/bossung-curve.md","filePath":"litho/bossung-curve.md","lastUpdated":1791413859000}'),p={name:"litho/bossung-curve.md"};function u(m,a,h,D,g,C){const E=A("Mermaid");return e(),d("div",null,[a[2]||(a[2]=r('<h1 id="bossung-曲线" tabindex="-1">Bossung 曲线 <a class="header-anchor" href="#bossung-曲线" aria-label="Permalink to &quot;Bossung 曲线&quot;">​</a></h1><div class="epigraph"><p>光学焦深给出一个轴向尺度；Bossung 把实验 CD 画成离焦的函数、按剂量分族，才看见这一层在硅片上还活着多宽。</p><footer>—— J. W. Bossung, Projection Printing Characterization, Proc. SPIE (1977) 以来的产线读图惯例</footer></div><p><a href="/litho/defocus-as-aberration">上一课</a>（离焦作为像差）。把离焦写成光瞳二次相位，并给出 \\(\\mathrm{DOF}\\propto\\lambda/\\mathrm{NA}^2\\)。缺口是：那条式子还在空中像里，没有胶阈值，也没有一张可以贴进报告的图。本课钉 Bossung 曲线：横轴离焦，纵轴 CD，每条曲线一个剂量。完整的曝光–散焦面积如何切规格，是后面工艺窗口课的题目；偏振在高 \\(\\mathrm{NA}\\) 下如何改这张图，留给<a href="/litho/vector-imaging">矢量成像</a>。不要从瑞利 CD 公式重讲分辨率——图形已经在印，本课只问它随焦面怎么走。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(k_2\\lambda/\\mathrm{NA}^2\\) 告诉数量级，不告诉「这一层、这一照明、这一胶」的可用焦深。曝光矩阵在晶圆上场间变剂量、变焦距，显影后量 CD，得到一族 \\(\\mathrm{CD}(z;E)\\)。规格带（例如目标 \\(\\pm 10\\%\\)）去切这些曲线，每个剂量得到一段可用 \\(z\\)；这才是实验焦深。缺口因此是读这张实验图，而不是再推一次二次相位。</p><p><span class="marginnote">数字实例：规格带 ±10% 时，目标 CD 40 nm 的层允许 36–44 nm。把每条剂量曲线与这条带求交，能留在带内的 z 区间就是该剂量的可用焦深；剂量一漂，交叠区间立刻变窄——这就是「剂量一漂，焦深还剩多少」的读法。</span></p><p>上一课已经点过 Bossung 的名字并把它推给 E–D 课。本课把图本身讲完：弯曲从哪来、何谓等焦、为何密线与孤立线不能共用一张。</p><h3 id="它不是调焦曲线的别名" tabindex="-1">它不是调焦曲线的别名 <a class="header-anchor" href="#它不是调焦曲线的别名" aria-label="Permalink to &quot;它不是调焦曲线的别名&quot;">​</a></h3><p>调焦传感器给出的是高度图；Bossung 给出的是<strong>印出的 CD</strong> 随设定离焦的变化。伺服可以把平均面放在「光学最佳」附近，Bossung 仍可能很弯——因为空中像调制随 \\(z\\) 变，阈值切点横移。把两者当成同一个「焦点好不好」，会漏掉胶和照明。</p><p><span class="marginnote">剂量族必须画在同一张图上。只看最佳剂量那一条，会把窗口压成线段，看不见剂量一漂焦深还剩多少。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>横轴：相对最佳焦面的 \\(z\\)（纳米）。纵轴：量得的 CD。参数：曝光剂量 \\(E\\)。正胶剂量升高通常使清掉区变宽（线变瘦或孔变大），整族曲线上下平移；离焦使调制变浅，曲线弯成笑或愁，视图形是密是疏、切在空中像的哪一段而定。</p><p><span class="marginnote">直觉类比：把 Bossung 读成「CD 的等高线地图」——横着走是离焦、上下是剂量，规格带是横穿地图的一条安全走廊。走廊越宽，这一层越好活；等焦剂量就是沿着走廊几乎不需要拐弯的那条路线。</span></p><p>等焦点（isofocal）附近，某条剂量的 CD 几乎不随 \\(z\\) 变：离焦掉对比与阈值切点的移动大致抵消。孤立线与密线的等焦剂量往往不同，所以「找到等焦」只对那一类图形成立，不能写成整层免费焦深。</p><h3 id="从曲线到窗口只差一步" tabindex="-1">从曲线到窗口只差一步 <a class="header-anchor" href="#从曲线到窗口只差一步" aria-label="Permalink to &quot;从曲线到窗口只差一步&quot;">​</a></h3><p>用规格带横切 Bossung，得到每个 \\(E\\) 的可用 DOF；再对 \\(E\\) 扫描，得到 E–D 平面上的合格区。曝光宽容度是最佳焦距处剂量轴的相对宽度。本课停在曲线：后课再谈面积与多图形重叠。这里只需承认 Bossung 是窗口的切片。</p><p><span class="marginnote">胶上 SEM 与刻蚀后 CD 不是同一族 Bossung。收缩、倒角、刻蚀偏置会把曲线搬家。写图要声明计量步骤。</span></p>',17)),(e(),t(i,null,{default:o(()=>[l(E,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E7%A6%BB%E7%84%A6%20z%22%5D%20--%3E%20BOSS%5B%22Bossung%3A%20CD(z%2C%20E)%22%5D%0A%20%20E%5B%22%E5%89%82%E9%87%8F%20E%22%5D%20--%3E%20BOSS%0A%20%20BOSS%20--%3E%20ISO%5B%22%E7%AD%89%E7%84%A6%E9%99%84%E8%BF%91%E8%BE%83%E5%B9%B3%22%5D%0A%20%20BOSS%20--%3E%20SPEC%5B%22%E8%A7%84%E6%A0%BC%E5%B8%A6%E6%A8%AA%E5%88%87%22%5D%0A%20%20SPEC%20--%3E%20ED%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AE%E2%80%93D%20%E9%9D%A2%E7%A7%AF%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[n("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"最佳焦面附近，空中像最陡，NILS 最高，剂量主要沿衬度曲线移动等剂量面，CD 随 \\(E\\) 单调。离焦后二次相位让各级失配，\\(C\\) 与 NILS 一起掉：要维持同一 CD，往往得改剂量，于是固定 \\(E\\) 的那条曲线在 \\(z\\) 方向弯下去或翻上来。三束成像弯得更急；两束成像（离轴）常常在焦轴上更宽——机制在焦深课讲过，这里是它的 CD 读出。",-1)),a[5]||(a[5]=s("p",null,"「禁戒节距」在 Bossung 上表现为某族曲线几乎没有平区：再怎么选剂量，离焦几十纳米就出规格。RET 换照明，本质是换哪一族 Bossung 变得可切。",-1)),a[6]||(a[6]=s("p",null,[s("span",{class:"marginnote"},"为什么重要：「禁戒节距」不是调焦没调好，而是该照明下两束衍射级几乎进不了光瞳，空中像随离焦塌得特别快——剂量怎么调都救不回来。出路是换照明结构（OAI）或换波长，这正是 RET 存在的理由。")],-1)),(e(),t(i,null,{default:o(()=>[l(E,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20DF%5B%22%E7%A6%BB%E7%84%A6%20z%20%E5%A2%9E%E5%A4%A7%22%5D%20--%3E%20PH%5B%22%E5%85%89%E7%9E%B3%E4%BA%8C%E6%AC%A1%E7%9B%B8%E4%BD%8D%E5%A2%9E%E5%8A%A0%22%5D%0A%20%20PH%20--%3E%20MIS%5B%22%E5%90%84%E7%BA%A7%E8%A1%8D%E5%B0%84%E5%A4%B1%E9%85%8D%22%5D%0A%20%20MIS%20--%3E%20CON%5B%22%E5%AF%B9%E6%AF%94%E5%BA%A6%E4%B8%8E%20NILS%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20CON%20--%3E%20TH%5B%22%E9%98%88%E5%80%BC%E5%88%87%E7%82%B9%E6%A8%AA%E7%A7%BB%22%5D%0A%20%20TH%20--%3E%20CD%5B%22%E5%9B%BA%E5%AE%9A%E5%89%82%E9%87%8F%20CD%20%E9%9A%8F%20z%20%E5%BC%AF%E5%87%BA%E8%A7%84%E6%A0%BC%E5%B8%A6%22%5D%0A%20%20CD%20--%3E%20FIX%5B%22%E6%94%B9%E5%89%82%E9%87%8F%E6%88%96%E6%8D%A2%E7%85%A7%E6%98%8E%EF%BC%88RET%EF%BC%89%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到实验焦深，默认去看 Bossung 被规格带切出的 \\(z\\) 宽度，并声明剂量与图形。光学 \\(\\mathrm{DOF}=k_2\\lambda/\\mathrm{NA}^2\\) 只提供尺度，不替代这张图。矢量课会改 \\(I(z)\\)，因而改弯曲，定义不变。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Bossung 不含套刻，不含跨场镜头指纹的全部——除非每个场点各画一张。曝光矩阵消耗晶圆与机时，产线常用稀疏场加模拟补密；模拟没有校准过的胶模型时，弯曲形状不可信。本课不引用未公开的某代机台焦深验收表。</p><p>也不要把「曲线很平」写成 NILS 很高：等焦可以来自对比与切点的抵消，窗口边沿的侧壁和残胶仍可能先死。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Bossung：\\(\\mathrm{CD}\\) vs 离焦，按剂量分族，是实验焦深的读图。</li><li>光学 \\(\\lambda/\\mathrm{NA}^2\\) 给尺度；硅片曲线给这一层的可用宽度。</li><li>等焦只对特定图形与剂量成立。</li><li>规格带横切之后才进入 E–D 面积。</li><li>计量步骤必须声明（显影后 / 刻蚀后）。</li><li>出处：Bossung, Proc. SPIE (1977)；读图惯例见 Mack、Levinson。</li></ul>',7))])}const S=B(p,[["render",u]]);export{b as __pageData,S as default};
